const views=$$(".view"),state={mode:"emotion",monsters:[],activeIndex:0,combo:0,maxCombo:0,totalDamage:0,battleStarted:0,comboTimer:null,rushTimer:null,sound:true,saveRaw:false,deferredInstall:null,speechTimer:null,attackHistory:[],rush:false,finishing:false,fx:null,session:0};
