function setupMode(mode){state.mode=mode;const emotion=mode==="emotion";$("#modeBadge").textContent=emotion?"脑内作乱":"人间奇葩";$("#promptTitle").textContent=emotion?"现在什么东西在折磨你？":"今天又碰见什么玩意儿了？";$("#ventInput").placeholder=emotion?"随便说，不用组织语言，也不用文明……":"说吧，谁又干了什么破事……";const examples=emotion?["怕别人超过我","脑子一直瞎想","工作、别人和未来全压着我"]:["同事又阴阳怪气","那个人抢功还邀功","总有人对我指手画脚"];$("#exampleChips").innerHTML=examples.map(x=>`<button>${x}</button>`).join("");$("#ventInput").value="";updateInput();showView("inputView");setTimeout(()=>$("#ventInput").focus(),250)}
