function normalDNA(d={}){const oldMap={pear:"tall",round:"blob",slug:"parasite",spike:"tank"};return{...d,id:d.id||`old-${Date.now()}`,rarity:d.rarity||"COMMON",maxHp:d.maxHp||100,hp:d.hp??d.maxHp??100,archetype:d.archetype||oldMap[d.bodyShape]||d.bodyShape||"blob",visualTraits:d.visualTraits||[],accentColor:d.accentColor||"#ffd04a",primaryColor:d.primaryColor||"#a66cff",secondaryColor:d.secondaryColor||"#492d86",eyes:d.eyes||2,mouth:d.mouth||"grin",arms:Number.isFinite(d.arms)?d.arms:(d.arms?2:0),legs:Number.isFinite(d.legs)?d.legs:(d.legs?2:0),movementStyle:d.movementStyle||"jitter",insultLines:d.insultLines||d.idleLines||["看什么看？"],panicLines:d.panicLines||d.mediumHitLines||["等等……"],lowHpLines:d.lowHpLines||d.heavyHitLines||["别打了！"],defeatedLines:d.defeatedLines||d.surrenderLines||["我认输！"],phases:d.phases||[]}}
const rect=(x,y,w,h,fill,extra="")=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${fill}" ${extra}/>`;
function limbs(d){let out="";const armYs=[58,70,82];for(let i=0;i<d.arms/2;i++){const y=armYs[i%3];out+=`<path d="M31 ${y}H${18-i*3}V${y+(i%2?10:-8)}H${11-i*2}M97 ${y}h${13+i*3}v${i%2?10:-8}h${7+i*2}" fill="none" stroke="${d.secondaryColor}" stroke-width="5"/>`}for(let i=0;i<d.legs/2;i++){const x1=46-i*7,x2=82+i*7;out+=`<path d="M${x1} 96v14h-9M${x2} 96v14h9" fill="none" stroke="${d.secondaryColor}" stroke-width="6"/>`}return out}
function freeBody(d){const b=d.blueprint,p=d.primaryColor,s=d.secondaryColor,a=d.accentColor,w=Math.round(54*b.width),h=Math.round(55*b.height),x=Math.round(64-w/2),y=Math.round(64-h/2),count=b.coreCount||1;let o="";for(let i=0;i<count;i++){const ox=b.symmetry==="lopsided"?i*9:(i-(count-1)/2)*13,oy=b.symmetry==="stacked"?-i*15:(i%2)*7,ww=Math.max(20,w-i*8),hh=Math.max(22,h-i*5);if(["spiral","coil","loop"].includes(b.coreShape))o+=`<path d="M${x+ox} ${y+oy+hh/2}h${ww}v${hh/2}H${x+ox+8}V${y+oy+9}h${ww-16}v${hh-18}H${x+ox+17}v-${Math.max(8,hh-30)}h${Math.max(12,ww-34)}" fill="none" stroke="${i%2?p:s}" stroke-width="8"/>`;else if(["zigzag","spike","tangle"].includes(b.coreShape))o+=`<path d="M${x+ox} ${y+oy+hh*.28}  ${x+ox+ww*.28} ${y+oy} ${x+ox+ww*.46} ${y+oy+hh*.24} ${x+ox+ww*.72} ${y+oy+4} ${x+ox+ww} ${y+oy+hh*.35} ${x+ox+ww*.84} ${y+oy+hh} ${x+ox+ww*.22} ${y+oy+hh*.9}Z" fill="${i%2?s:p}" stroke="#171221" stroke-width="4"/>`;else o+=`<path d="M${x+ox+8} ${y+oy}h${ww-16}v7h8v${hh-14}h-8v7H${x+ox+7}v-7H${x+ox}V${y+oy+8}h8Z" fill="${i%2?s:p}" stroke="#171221" stroke-width="4"/>`}if(b.material==="paper")o+=`<path d="M${x+10} ${y+13}h${w-20}M${x+10} ${y+26}h${w-30}" stroke="${a}" stroke-width="3"/>`;if(b.material==="metal")o+=`${rect(x+5,y+5,7,7,a)}${rect(x+w-12,y+h-12,7,7,a)}`;if(b.material==="glitch")o+=`${rect(x-7,y+20,21,6,a)}${rect(x+w-8,y+h-25,20,7,a)}`;return o}
function body(d){const p=d.primaryColor,s=d.secondaryColor,a=d.accentColor;if(d.blueprint)return freeBody(d);switch(d.archetype){case"tall":return`<path d="M48 18h32v8h8v68h-8v12H47V94h-8V30h9Z" fill="${p}" stroke="#171221" stroke-width="4"/>${rect(55,26,9,61,s)}`;case"tank":return`<path d="M24 39h12V28h56v11h12v56H93v11H35V95H24Z" fill="${p}" stroke="#171221" stroke-width="5"/>${rect(31,47,66,12,s)}`;case"bug":return`<path d="M45 31h38v15h10v44H82v17H46V90H35V46h10Z" fill="${p}" stroke="#171221" stroke-width="4"/>${rect(48,49,32,12,s)}${rect(48,68,32,12,s)}<path d="M48 33 35 17m45 16 13-16" stroke="${a}" stroke-width="4"/>`;case"floating_head":return`<path d="M29 29h70v10h10v49H98v11H30V89H19V40h10Z" fill="${p}" stroke="#171221" stroke-width="5"/>`;case"eye":return`<path d="M18 63q20-33 46-33t46 33q-20 34-46 34T18 63Z" fill="${p}" stroke="#171221" stroke-width="5"/>`;case"mouth":return`<path d="M24 34h80v12h9v47h-12v13H27V94H15V47h9Z" fill="${p}" stroke="#171221" stroke-width="5"/>`;case"shadow":return`<path d="M64 13 82 35l20 8-9 19 13 25-21 2-9 23-16-14-22 12-5-22-18-9 12-20-6-24 23 1Z" fill="#181520" stroke="${p}" stroke-width="5"/>`;case"mechanical":return`<path d="M29 29h70v70H29Z" fill="${s}" stroke="#171221" stroke-width="5"/>${rect(35,35,58,52,p)}${rect(58,15,12,14,a)}${rect(53,10,22,5,"#171221")}`;case"mimic":return`<path d="M35 25h58v17h10v62H25V42h10Z" fill="${p}" stroke="#171221" stroke-width="5"/>${rect(32,46,64,10,s)}${rect(55,18,18,9,a)}`;case"multi_head":return`<path d="M18 35h32v42H18Zm46-15h39v54H64Zm-1 62h43v30H25V80Z" fill="${p}" stroke="#171221" stroke-width="4"/>${rect(52,80,18,29,s)}`;case"multi_eye":return`<path d="M22 31h84v13h9v53h-13v12H27V97H14V44h8Z" fill="${p}" stroke="#171221" stroke-width="5"/>`;case"parasite":return`<path d="M42 45h45v9h12v39H86v17H43V98H29V58h13Z" fill="${p}" stroke="#171221" stroke-width="4"/>`;case"boss":return`<path d="M19 24h25V13h40v11h25v16h11v60h-16v15H24v-15H8V40h11Z" fill="${p}" stroke="#171221" stroke-width="6"/>${rect(19,45,90,13,s)}${rect(49,20,30,86,s,'opacity=".38"')}`;default:return`<path d="M29 35h12V24h47v11h12v12h10v45H99v13H29V96H18V47h11Z" fill="${p}" stroke="#171221" stroke-width="5"/>`}}
function eyes(d,hurt){if(d.archetype==="eye")return`<rect x="35" y="47" width="58" height="34" fill="#fff8dc" stroke="#171221" stroke-width="4"/>${rect(hurt>60?62:57,52,15,24,"#171221")}${rect(61,55,4,5,"white")}`;const count=Math.min(d.eyes,d.archetype==="multi_eye"?9:4),spots=count===1?[[64,55]]:count===2?[[49,52],[79,52]]:count===3?[[40,52],[64,43],[88,52]]:[[39,45],[62,42],[86,45],[64,64]];return spots.slice(0,count).map(([x,y],i)=>`${rect(x-7,y-6,14,hurt>65?7:15,"#fff8dc")}${rect(x+(d.eyeExpression==="side-eye"?1:-2),y-2,5,hurt>65?5:8,"#171221")}${d.visualTraits.includes("highBrow")?rect(x-8,y-12,16,3,"#171221",`transform="rotate(${i%2?-8:8} ${x} ${y})"`):""}`).join("")}
function mouth(d,hurt){if(d.archetype==="eye")return"";const y=d.archetype==="tall"?77:76;if(hurt>78)return`<path d="M49 ${y+8}h29v-5h8" fill="none" stroke="#171221" stroke-width="5"/>`;if(d.mouth==="huge"||d.archetype==="mouth")return`<rect x="35" y="67" width="58" height="28" fill="#171221"/><path d="M39 70h50l-7 8-7-8-7 8-8-8-7 8-7-8Z" fill="#fff8dc"/>`;if(d.mouth==="crooked")return`<path d="M46 ${y}h18v5h25" fill="none" stroke="#171221" stroke-width="6"/>${rect(92,y-10,6,6,d.accentColor)}`;return d.mouth==="frown"?`<path d="M48 ${y+8}v-5h32v5" fill="none" stroke="#171221" stroke-width="5"/>`:`<path d="M46 ${y}h39v-6" fill="none" stroke="#171221" stroke-width="5"/>`}
function extras(d){const t=d.visualTraits,a=d.accentColor;let o="";if(t.includes("twoFaces"))o+=`${rect(64,30,36,62,d.secondaryColor,'opacity=".72"')}${rect(92,47,9,14,"#fff8dc")}${rect(94,51,4,7,"#171221")}`;if(t.includes("manyEyes")&&d.eyes>4){for(let i=0;i<d.eyes-4;i++)o+=`${rect(31+i*13,87+(i%2)*7,9,7,"#fff8dc")}${rect(34+i*13,89+(i%2)*7,3,4,"#171221")}`}if(t.includes("medals")||d.accessory==="medals")o+=`${rect(52,92,8,12,a)}${rect(68,92,8,12,a)}${rect(50,101,12,10,"#ffd04a")}${rect(66,101,12,10,"#ffd04a")}`;if(t.includes("megaphone")||d.accessory==="megaphone")o+=`<path d="M94 55h14l13-10v30l-13-9H94Z" fill="${a}" stroke="#171221" stroke-width="3"/>`;if(t.includes("clock")||d.accessory==="clock")o+=`${rect(48,18,33,28,"#fff8dc",'stroke="#171221" stroke-width="3"')}${rect(62,22,4,12,"#171221")}${rect(64,32,10,4,"#171221")}`;if(t.includes("rankboard"))o+=`${rect(12,13,36,22,"#1b1827",'stroke="#ffd04a" stroke-width="3"')}<text x="18" y="28" fill="#ffd04a" font-size="10" font-weight="900">#02</text>`;if(t.includes("boulder"))o+=`<path d="M79 8h29l12 17-9 25H78L67 29Z" fill="#656174" stroke="#171221" stroke-width="4"/>`;if(t.includes("manyArms"))o+=`<path d="M30 53H8v-9m22 25H4v10m94-27h23v-9M98 70h26v11" fill="none" stroke="${d.secondaryColor}" stroke-width="5"/>`;if(t.includes("trophy")||d.accessory==="trophy")o+=`<path d="M50 20h28v15l-7 8H57l-7-8Zm0 4H39v9h11m28-9h11v9H78" fill="${a}" stroke="#171221" stroke-width="3"/>`;if(t.includes("mask"))o+=`<path d="M38 43h53v24l-14 10H52L38 67Z" fill="#f5ead7" opacity=".78" stroke="#171221" stroke-width="3"/>`;if(t.includes("spotlight"))o+=`<path d="M19 4h24l34 92H44Z" fill="${a}" opacity=".18"/>${rect(17,4,29,9,a)}`;if(t.includes("screen"))o+=`${rect(37,29,56,39,"#1a1830",'stroke="#65edd7" stroke-width="4"')}${rect(44,37,31,5,a)}${rect(44,49,40,4,d.primaryColor)}`;if(t.includes("labels"))o+=`${rect(16,81,30,12,"#fff1b8",'transform="rotate(-8 31 87)"')}${rect(82,24,29,12,"#fff1b8",'transform="rotate(7 96 30)"')}`;if(t.includes("closedDoor"))o+=`${rect(42,22,45,78,"#322a4f",'stroke="#171221" stroke-width="5"')}${rect(75,59,5,5,a)}`;if(t.includes("emptyChair"))o+=`<path d="M91 74h25v20H96v18m-3-38V55h19v19" fill="none" stroke="${a}" stroke-width="5"/>`;if(t.includes("strings"))o+=`<path d="M35 8v36m28-36v31m29-31v36" stroke="#e9e2f1" stroke-width="2" stroke-dasharray="4 3"/>`;if(t.includes("needles"))o+=`<path d="m17 45-14-8 14-4m94 19 14-8-14-4M25 90 9 97m93-8 17 8" stroke="${a}" stroke-width="4"/>`;if(t.includes("radar"))o+=`<path d="M84 30a22 22 0 1 1-1 0m1 0-15 16" fill="none" stroke="${a}" stroke-width="3"/>`;if(t.includes("coil")||t.includes("knots"))o+=`<path d="M12 102q22-29 43 0t42 0 22-17" fill="none" stroke="${a}" stroke-width="5"/>`;if(t.includes("ropes"))o+=`<path d="M5 18 37 48m86-29L91 49M7 112l35-28m78 31L88 85" stroke="#e8e1cf" stroke-width="3" stroke-dasharray="6 3"/>`;if(t.includes("flames")||t.includes("steam"))o+=`<path d="M30 31q-10-14 2-22m65 24q12-15 1-25M16 74Q2 62 10 49" fill="none" stroke="${a}" stroke-width="5"/>`;if(t.includes("repeat"))o+=`<text x="10" y="120" fill="${a}" font-size="13" font-weight="900">LOOP LOOP</text>`;if(d.horns)o+=`<path d="m39 34-8-21 19 13m38 8 9-21-20 13" fill="${a}" stroke="#171221" stroke-width="3"/>`;if(d.rarity==="RARE"||d.rarity==="BOSS")o+=`<path d="M11 30h8v8h-8zm96-13h8v8h-8zM10 92h7v7h-7zm102 3h8v8h-8z" fill="${a}"/>`;return o}
export function monsterSVG(raw,hurt=0){const d=normalDNA(raw);return`<svg class="monster-svg" viewBox="0 0 128 128" role="img" aria-label="${esc(d.name)}" shape-rendering="crispEdges"><g class="monster-core">${limbs(d)}${body(d)}${eyes(d,hurt)}${mouth(d,hurt)}${extras(d)}</g></svg>`}
class AudioEngine{constructor(){this.ctx=null;this.enabled=true}init(){if(!this.ctx)this.ctx=new(AudioContext||webkitAudioContext)();if(this.ctx.state==="suspended")this.ctx.resume()}play(type="punch",power=.5,combo=0){if(!this.enabled)return;this.init();const c=this.ctx,n=c.currentTime,o=c.createOscillator(),g=c.createGain(),f=c.createBiquadFilter(),cfg={punch:[145,65,"square",.08],slap:[260,75,"sawtooth",.13],uppercut:[130,410,"square",.18],smash:[95,28,"sawtooth",.23],heavy:[82,25,"sawtooth",.28],wall:[55,32,"square",.18],ko:[360,45,"square",.42],rush:[210,80,"square",.06]}[type]||[150,60,"square",.1];o.type=cfg[2];o.frequency.setValueAtTime(cfg[0]+combo*2,n);if(type==="uppercut")o.frequency.exponentialRampToValueAtTime(cfg[1],n+cfg[3]);else o.frequency.exponentialRampToValueAtTime(Math.max(20,cfg[1]),n+cfg[3]);f.type="lowpass";f.frequency.value=type==="slap"?1600:900;g.gain.setValueAtTime(.0001,n);g.gain.exponentialRampToValueAtTime(.07+power*.14,n+.006);g.gain.exponentialRampToValueAtTime(.0001,n+cfg[3]);o.connect(f).connect(g).connect(c.destination);o.start();o.stop(n+cfg[3]+.02);navigator.vibrate?.(type==="heavy"||type==="smash"?[24,15,30]:8+Math.round(power*10))}}
const sounds=new GameAudio();
function layoutFor(count,index,boss=false){if(count===1)return{x:0,y:boss?28:43,s:boss?1.04:1};if(count===2)return[{x:-91,y:62,s:.7},{x:91,y:43,s:.73}][index];return[{x:-112,y:76,s:.58},{x:0,y:35,s:.64},{x:112,y:76,s:.56}][index]}
function arenaTheme(d){if(/credit|passive|hypocrisy|showing/.test(d.category))return"bg-office";if(/anger|grievance|blame/.test(d.category))return"bg-junk";return"bg-void"}
function cleanupBattle(){state.session++;clearTimeout(state.comboTimer);clearTimeout(state.speechTimer);clearInterval(state.rushTimer);state.fx?.destroy();state.fx=null;sounds.releaseBattle(true);const arena=$("#arena");if(arena)arena.replaceChildren();$("#finisherChoices")?.replaceChildren();$$('.particle,.damage-number,.shockwave').forEach(x=>x.remove());state.monsters=[];state.attackHistory=[];state.rush=false;state.finishing=false}
async function startBattle(text){if(hasImmediateSafetyRisk(text)){showView("safetyView");return}const records=await getAllMonsters(),familiarity=Object.fromEntries(records.map(r=>[r.category,r.appearances]));state.monsters=generateMonsters(text,state.mode,familiarity).map((raw,index)=>{const dna=normalDNA(raw);return{dna,hp:dna.maxHp,maxHp:dna.maxHp,state:"嚣张",defeated:false,finisherDone:false,x:0,y:0,rot:0,index,phase:0}});state.activeIndex=0;state.combo=0;state.maxCombo=0;state.totalDamage=0;state.battleStarted=Date.now();state.attackHistory=[];state.rush=false;state.finishing=false;state.session++;$("#comboCount").textContent="0";$(".combo-wrap").classList.remove("active");$("#combatBanner").classList.remove("show");$("#speechBubble").classList.remove("show");for(const m of state.monsters)await saveEncounter(m.dna,text,state.saveRaw);showView("battleView");renderBattle();state.fx?.destroy();state.fx=new PixelFX($("#arena"));sounds.startBattle(state.monsters.some(m=>m.dna.rarity==="BOSS"));setTimeout(()=>{if(state.monsters.length)speak(activeMonster().dna.idleLines[0])},600)}
function renderBattle(){const arena=$("#arena");arena.className=`arena ${arenaTheme(state.monsters[0].dna)}`;arena.innerHTML="";state.monsters.forEach((m,i)=>{const pos=layoutFor(state.monsters.length,i,m.dna.rarity==="BOSS");m.x=pos.x;m.y=pos.y;const el=document.createElement("div");el.className=`monster-wrap idle ${i===0?"target":""} ${m.dna.rarity==="BOSS"?"boss":""}`;el.dataset.index=i;el.dataset.move=m.dna.movementStyle;el.style.cssText=`--x:${pos.x}px;--y:${pos.y}px;--rot:0deg;--scale:${pos.s*m.dna.bodySize}`;el.innerHTML=monsterSVG(m.dna,0);arena.appendChild(el);attachGestures(el,i)});$("#finisherPanel").classList.remove("show");$("#battleEnd").classList.remove("show");renderRoster();updateHud()}
function renderRoster(){$("#roster").innerHTML=state.monsters.map((m,i)=>`<button data-target="${i}" class="${i===state.activeIndex?"active":""}" ${m.defeated?"disabled":""}><strong>${esc(m.dna.name)}</strong><small>${m.defeated?"已消灭":`${m.dna.rarity} · ${m.state}`}</small><span class="mini-hp"><i style="width:${Math.max(0,m.hp/m.maxHp*100)}%"></i></span></button>`).join("")}
const activeMonster=()=>state.monsters[state.activeIndex],activeElement=()=>$(`.monster-wrap[data-index="${state.activeIndex}"]`);
function selectMonster(index){const m=state.monsters[index];if(!m||m.defeated||state.finishing)return;state.activeIndex=index;$$('.monster-wrap').forEach((e,i)=>e.classList.toggle("target",i===index));renderRoster();updateHud();speak(m.dna.idleLines[Math.floor(Math.random()*m.dna.idleLines.length)])}
function phaseOf(m){const ratio=m.hp/m.maxHp;if(m.dna.rarity!=="BOSS")return"";return m.dna.phases[ratio>.66?0:ratio>.33?1:2]}
function updateHud(){const m=activeMonster();if(!m)return;$("#enemyRarity").textContent=m.dna.rarity;$("#enemyRarity").style.color=rarityColor[m.dna.rarity];$("#enemyName").textContent=m.dna.name;$("#enemyPhase").textContent=phaseOf(m);const pct=Math.max(0,m.hp/m.maxHp*100);$("#hpFill").style.width=`${pct}%`;$("#hpFill").style.background=pct>40?"#d9ff43":pct>15?"#ffd04a":"#ff4773";$("#hpText").textContent=`${Math.ceil(m.hp)} / ${m.maxHp}`}
function speak(line,duration=1450){const b=$("#speechBubble");b.textContent=line;b.classList.add("show");clearTimeout(state.speechTimer);state.speechTimer=setTimeout(()=>b.classList.remove("show"),duration)}
function banner(text){const b=$("#combatBanner");b.textContent=text;b.classList.remove("show");void b.offsetWidth;b.classList.add("show")}
function impact(x,y,power,type,damage,critical=false,wall=false){const a=$("#arena"),colors=["#d9ff43","#ff4773","#58e8e1","#ffd04a","#fff9e9"];state.fx?.hit({x:x-5,y:y-5,width:10,height:10},colors,Math.min(1,power+state.combo*.012));const n=document.createElement("b");n.className=`damage-number ${critical?"critical":""} ${wall?"wall":""}`;n.textContent=`${critical?"CRITICAL ":wall?"WALL ":""}-${damage}`;n.style.cssText=`--px:${Math.max(18,x-35)}px;--py:${Math.max(90,y-25)}px`;a.appendChild(n);setTimeout(()=>n.remove(),800);if(power>.72){const w=document.createElement("i");w.className="shockwave";w.style.cssText=`--px:${x}px;--py:${y}px`;a.appendChild(w);setTimeout(()=>w.remove(),500)}}
const attacks={punch:{range:[5,8],power:.35,cls:"hit",stop:30},slap:{range:[12,18],power:.62,cls:"slap",stop:55},uppercut:{range:[18,25],power:.75,cls:"uppercut",stop:75},smash:{range:[20,30],power:.85,cls:"smash",stop:90},slam:{range:[24,36],power:.9,cls:"smash",stop:95},spin:{range:[27,40],power:1,cls:"slap",stop:100},heavy:{range:[10,60],power:1,cls:"heavy",stop:110},rush:{range:[3,5],power:.4,cls:"hit",stop:18}};
function randomDamage([a,b]){return Math.round(a+Math.random()*(b-a))}
function updateCondition(m,el){const pct=m.hp/m.maxHp;if(pct>.7){m.state="嚣张";el.classList.remove("panic","low")}else if(pct>.4){m.state="开始惊讶";el.classList.remove("panic","low")}else if(pct>.15){m.state="明显害怕";el.classList.add("panic");el.classList.remove("low")}else{m.state="濒败";el.classList.add("panic","low")}}
function applyAttack(index,type,point,vector={x:0,y:0},charge=0,synthetic=false){const m=state.monsters[index];if(!m||m.defeated||m.hp<=0||state.finishing)return;selectMonster(index);const cfg=attacks[type],el=activeElement();let base=type==="heavy"?Math.round(10+Math.min(1,charge)*50):randomDamage(cfg.range);const crit=charge>=.98||Math.random()<Math.min(.24,.07+state.combo*.007),comboBoost=1+Math.min(.3,state.combo*.012);let damage=Math.round(base*comboBoost*(crit?1.34:1));state.combo++;state.maxCombo=Math.max(state.maxCombo,state.combo);sounds.combo(state.combo);$("#comboCount").textContent=state.combo;$(".combo-wrap").classList.add("active");clearTimeout(state.comboTimer);state.comboTimer=setTimeout(()=>{state.combo=0;$(".combo-wrap").classList.remove("active")},1250);
  el.classList.remove("hit","slap","uppercut","smash","heavy","hurt");document.body.classList.add("hitstop");setTimeout(()=>{document.body.classList.remove("hitstop");el.classList.add(cfg.cls,"hurt");setTimeout(()=>el.classList.remove(cfg.cls,"hurt"),600)},cfg.stop);
  let wall=false;if(["slap","spin","heavy"].includes(type)){const push=Math.max(-210,Math.min(210,vector.x*(type==="spin"?1.25:.72)));m.x+=push;m.rot+=Math.max(-45,Math.min(45,vector.x*.16));if(Math.abs(m.x)>innerWidth*.32){wall=true;damage+=8;m.x=Math.sign(m.x)*innerWidth*.31;sounds.play("wall",{gain:.9});banner("WALL HIT +8")}el.style.transition=`transform ${type==="spin"?.25:.16}s steps(4)`;el.style.setProperty("--x",`${m.x}px`);el.style.setProperty("--rot",`${m.rot}deg`);setTimeout(()=>{if(m.hp>0){const home=layoutFor(state.monsters.length,index,m.dna.rarity==="BOSS");m.x=home.x;m.y=home.y;m.rot=0;el.style.transition="transform .48s steps(7)";el.style.setProperty("--x",`${home.x}px`);el.style.setProperty("--y",`${home.y}px`);el.style.setProperty("--rot","0deg");setTimeout(()=>el.style.transition="",500)}},360)}
  m.hp=Math.max(0,m.hp-damage);state.totalDamage+=damage;updateCondition(m,el);updateHud();renderRoster();impact(point.x,point.y,cfg.power,type,damage,crit,wall);sounds.play(crit?"critical":type,{gain:Math.min(1,.68+cfg.power*.3),rate:1+Math.min(.25,state.combo*.008)});sounds.lowHp(m.hp/m.maxHp<.18&&m.hp>0);navigator.vibrate?.(type==="heavy"||type==="smash"?[24,15,30]:8+Math.round(cfg.power*10));if(type==="smash"||type==="slam"||type==="heavy"||crit){$("#battleView").classList.add(type==="heavy"||crit?"screen-shake-hard":"screen-shake");if(crit)$("#battleView").classList.add("screen-flash");setTimeout(()=>$("#battleView").classList.remove("screen-shake","screen-shake-hard","screen-flash"),390)}
  const pct=m.hp/m.maxHp,lines=pct>.7?(m.dna.lightHitLines||m.dna.insultLines):pct>.4?m.dna.mediumHitLines:pct>.15?m.dna.panicLines:m.dna.lowHpLines;speak(lines[Math.floor(Math.random()*lines.length)]);if(crit)banner(charge>=.98?`MAX CHARGE · -${damage}`:`CRITICAL · -${damage}`);else if(type==="uppercut")banner(`UPPERCUT · -${damage}`);else if(type==="smash"||type==="slam")banner(`GROUND SMASH · -${damage}`);else if(type==="spin")banner(`SPIN THROW · -${damage}`);
  state.attackHistory.push({type,dir:Math.sign(vector.x),at:performance.now()});state.attackHistory=state.attackHistory.filter(h=>performance.now()-h.at<1600);if(!synthetic)checkSpecial(index,point);if(m.hp<=0)setTimeout(()=>knockout(index),620)}
function checkSpecial(index,point){if(state.combo===10&&!state.rush){state.rush=true;banner("RUSH MODE!");let hits=0;clearInterval(state.rushTimer);state.rushTimer=setInterval(()=>{const m=state.monsters[index];if(!m||m.hp<=0||hits++>=7){clearInterval(state.rushTimer);state.rush=false;return}applyAttack(index,"rush",{x:point.x+(Math.random()-.5)*70,y:point.y+(Math.random()-.5)*70},{},0,true)},95)}const slaps=state.attackHistory.filter(h=>h.type==="slap").slice(-4);if(slaps.length===4&&slaps.every((h,i)=>i===0||h.dir!==slaps[i-1].dir)){state.attackHistory=[];banner("SLAP COMBO!");for(let i=0;i<3;i++)setTimeout(()=>applyAttack(index,"rush",{x:point.x+(i-1)*30,y:point.y},{x:i%2?100:-100},0,true),i*100)}}
function knockout(index){const m=state.monsters[index];if(!m||m.hp>0||m.ko)return;m.ko=true;m.state="等待终结";state.finishing=true;sounds.lowHp(false);sounds.enterFinisher();const el=$(`.monster-wrap[data-index="${index}"]`);el.classList.add("ko");sounds.play("ko",{gain:1});banner("K.O.");speak(m.dna.defeatedLines[Math.floor(Math.random()*m.dna.defeatedLines.length)],1800);renderRoster();setTimeout(()=>showFinisher(index),900)}
const finishers=[{id:"delete",icon:"⌫",label:"DELETE",cls:"fin-delete"},{id:"crush",icon:"▰",label:"压成像素饼",cls:"fin-crush"},{id:"launch",icon:"▲",label:"踢飞到太空",cls:"fin-launch"},{id:"void",icon:"◎",label:"黑洞吸走",cls:"fin-void"},{id:"burst",icon:"✦",label:"像素粉碎",cls:"fin-delete"}];
function showFinisher(index){const shuffled=[...finishers].sort(()=>Math.random()-.5).slice(0,3);$("#finisherChoices").innerHTML=shuffled.map(f=>`<button data-finish="${f.id}" data-index="${index}"><span>${f.icon}</span>${f.label}</button>`).join("");$("#finisherPanel").classList.add("show")}
async function executeFinisher(index,id){const m=state.monsters[index];if(!m||m.finisherDone)return;m.finisherDone=true;const f=finishers.find(x=>x.id===id)||finishers[0],el=$(`.monster-wrap[data-index="${index}"]`);$("#finisherPanel").classList.remove("show");banner(id==="delete"?"ERROR → DELETED":id==="crush"?"1 TON CRUSH":id==="launch"?"TO THE MOON!":id==="void"?"VOIDED":"PIXEL BREAK!");el.classList.add(f.cls);$("#battleView").classList.add("screen-shake-hard","screen-flash");const r=el.getBoundingClientRect();sounds.finish();await state.fx?.finisher(id,r,[m.dna.primaryColor,m.dna.secondaryColor,m.dna.accentColor,"#fff9e9"]);$("#battleView").classList.remove("screen-shake-hard","screen-flash");await markDefeated(m.dna.category);m.defeated=true;state.finishing=false;renderRoster();const next=state.monsters.findIndex(x=>!x.defeated);if(next>=0){selectMonster(next);sounds.startBattle(next>=0&&state.monsters[next].dna.rarity==="BOSS")}else setTimeout(showBattleEnd,420)}
function showBattleEnd(){const elapsed=Math.max(1,Math.round((Date.now()-state.battleStarted)/1000)),minutes=String(Math.floor(elapsed/60)).padStart(2,"0"),seconds=String(elapsed%60).padStart(2,"0");$("#endEyebrow").textContent=`${state.monsters.length} TARGET${state.monsters.length>1?"S":""} ELIMINATED`;$("#endTitle").textContent=Math.random()>.5?"清净了。":"全部消灭。";$("#resultMonster").textContent=state.monsters.map(m=>m.dna.name).join(" / ");$("#resultTime").textContent=`${minutes}:${seconds}`;$("#resultCombo").textContent=`${state.maxCombo} HIT`;$("#resultDamage").textContent=String(state.totalDamage);$("#battleEnd").classList.add("show");sounds.victory()}
function attachGestures(el,index){let start=null,last=null,path=[],chargeTimer=null,charging=false,pointer=null;el.addEventListener("pointerdown",e=>{const m=state.monsters[index];if(!m||m.hp<=0||state.finishing)return;selectMonster(index);pointer=e.pointerId;el.setPointerCapture(pointer);start=last={x:e.clientX,y:e.clientY,t:performance.now()};path=[start];chargeTimer=setTimeout(()=>{charging=true;el.classList.add("charging");banner("CHARGING...")},300)});el.addEventListener("pointermove",e=>{if(!start||e.pointerId!==pointer)return;const now={x:e.clientX,y:e.clientY,t:performance.now()};path.push(now);if(path.length>14)path.shift();const dist=Math.hypot(now.x-start.x,now.y-start.y);if(dist>15&&now.t-start.t<300){clearTimeout(chargeTimer);charging=false}if(dist>25){el.classList.add("dragging");const m=state.monsters[index];el.style.setProperty("--x",`${m.x+now.x-start.x}px`);el.style.setProperty("--y",`${m.y+now.y-start.y}px`)}last=now});const end=e=>{if(!start||e.pointerId!==pointer)return;clearTimeout(chargeTimer);const now={x:e.clientX,y:e.clientY,t:performance.now()},dx=now.x-start.x,dy=now.y-start.y,dist=Math.hypot(dx,dy),duration=now.t-start.t;let turn=0;for(let i=2;i<path.length;i++){const a=Math.atan2(path[i-1].y-path[i-2].y,path[i-1].x-path[i-2].x),b=Math.atan2(path[i].y-path[i-1].y,path[i].x-path[i-1].x);turn+=Math.abs(Math.atan2(Math.sin(b-a),Math.cos(b-a)))}el.classList.remove("dragging","charging");const m=state.monsters[index];el.style.setProperty("--x",`${m.x}px`);el.style.setProperty("--y",`${m.y}px`);const point={x:now.x,y:now.y};if(turn>3.5&&dist>35)applyAttack(index,"spin",point,{x:dx||120,y:dy},0);else if(duration>380&&dist>45)applyAttack(index,dy>25?"slam":"spin",point,{x:dx,y:dy},0);else if(duration>=280&&dist<45)applyAttack(index,"heavy",point,{x:dx,y:dy},Math.min(1,(duration-.28e3)/1220+.18));else if(dist<15)applyAttack(index,"punch",point);else if(Math.abs(dx)>Math.abs(dy)*1.2)applyAttack(index,"slap",point,{x:dx,y:dy});else if(dy<0)applyAttack(index,"uppercut",point,{x:dx,y:dy});else applyAttack(index,"smash",point,{x:dx,y:dy});start=last=null;path=[];charging=false;pointer=null};el.addEventListener("pointerup",end);el.addEventListener("pointercancel",()=>{clearTimeout(chargeTimer);el.classList.remove("dragging","charging");const m=state.monsters[index];if(m){el.style.setProperty("--x",`${m.x}px`);el.style.setProperty("--y",`${m.y}px`)}start=null;path=[];charging=false;pointer=null})}
async function renderDex(){const records=await getAllMonsters(),list=$("#dexList");$("#dexEmpty").classList.toggle("show",!records.length);list.innerHTML=records.map(r=>{const d=normalDNA(r.dna),status=r.defeats>=4?"看见你就开始掉帧":r.defeats?"已被你正式消灭过":"还没完成终结",anchor=d.semanticAnchor||d.blueprint?.material||"像素异形";return`<article class="dex-item"><div class="dex-avatar">${monsterSVG(d,r.defeats?72:0)}</div><div class="dex-copy"><h3>${esc(d.name)}</h3><span class="rarity-tag" style="color:${rarityColor[d.rarity]}">${d.rarity} · ${esc(anchor)}</span><p>${esc(d.visualExplanation||d.represents)}</p><div class="dex-meta"><span>HP ${d.maxHp}</span><span>出现 ${r.appearances} 次</span><span>被消灭 ${r.defeats||0} 次</span><span class="dex-status">${status}</span></div></div></article>`}).join("")}
function registerWebMCP(){const c=document.modelContext;if(!c?.registerTool)return;const ac=new AbortController();Promise.resolve(c.registerTool({name:"release_emotion_monsters",title:"放出像素情绪怪",description:"根据中文情绪或人际事件，在页面中本地生成像素怪物并进入街机战斗。",inputSchema:{type:"object",properties:{text:{type:"string",minLength:2,maxLength:280},mode:{type:"string",enum:["emotion","person"]}},required:["text","mode"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},async execute(input){if(!input||typeof input.text!=="string"||input.text.trim().length<2||!["emotion","person"].includes(input.mode))throw Error("请输入 2–280 字并选择模式");state.mode=input.mode;await startBattle(input.text.trim().slice(0,280));return{status:"battle_started",monsters:state.monsters.map(m=>({name:m.dna.name,rarity:m.dna.rarity,archetype:m.dna.archetype,hp:m.maxHp}))}}},{signal:ac.signal})).catch(()=>{})}
function bindEvents(){$$(".mode-card").forEach(b=>b.addEventListener("click",()=>{sounds.play("ui",{scope:"menu"});setupMode(b.dataset.mode)}));$("#ventInput").addEventListener("input",updateInput);$("#exampleChips").addEventListener("click",e=>{if(e.target.tagName!=="BUTTON")return;$("#ventInput").value=e.target.textContent;updateInput();$("#ventInput").focus()});$("#releaseBtn").addEventListener("click",()=>startBattle($("#ventInput").value.trim()));$$('[data-back="home"],#homeBtn,#endHomeBtn,#safetyHomeBtn').forEach(b=>b.addEventListener("click",()=>showView("homeView")));$("#dexBtn").addEventListener("click",()=>showView("dexView"));$("#homeDexBtn").addEventListener("click",()=>showView("dexView"));$("#homeSettingsBtn").addEventListener("click",()=>$("#settingsDialog").showModal());$("#roster").addEventListener("click",e=>{const b=e.target.closest("button[data-target]");if(b)selectMonster(+b.dataset.target)});$("#finisherChoices").addEventListener("click",e=>{const b=e.target.closest("button[data-finish]");if(b)executeFinisher(+b.dataset.index,b.dataset.finish)});$("#againBtn").addEventListener("click",()=>setupMode(state.mode));const toggleSound=enabled=>{state.sound=enabled;sounds.setEnabled(enabled);$("#soundBtn").textContent=enabled?"◖))":"静音";$("#soundBtn").setAttribute("aria-pressed",String(!enabled));$("#menuSoundToggle").checked=enabled;setSetting("sound",enabled);if(enabled){sounds.play("ui",{scope:"menu"});sounds.startMenu()}};$("#soundBtn").addEventListener("click",()=>toggleSound(!state.sound));$("#menuSoundToggle").addEventListener("change",e=>toggleSound(e.target.checked));$("#saveRawToggle").addEventListener("change",e=>{state.saveRaw=e.target.checked;setSetting("saveRaw",state.saveRaw);toast(state.saveRaw?"今后会保留原始输入":"今后不再保留原始输入")});$("#clearDataBtn").addEventListener("click",()=>$("#confirmDialog").showModal());$("#confirmClearBtn").addEventListener("click",async()=>{await clearAllData();state.saveRaw=false;$("#saveRawToggle").checked=false;setTimeout(()=>{renderDex();toast("本地数据已清空")},80)});$("#installBtn").addEventListener("click",async()=>{if(state.deferredInstall){state.deferredInstall.prompt();await state.deferredInstall.userChoice;state.deferredInstall=null;$("#installBtn").classList.add("hidden")}else toast("在 Safari 分享菜单中选择“添加到主屏幕”")});addEventListener("beforeinstallprompt",e=>{e.preventDefault();state.deferredInstall=e;$("#installBtn").classList.remove("hidden")});addEventListener("pagehide",()=>{state.fx?.destroy();state.fx=null;sounds.destroy()},{once:true})}
async function init(){state.sound=await getSetting("sound",true);state.saveRaw=await getSetting("saveRaw",false);sounds.enabled=state.sound;$("#saveRawToggle").checked=state.saveRaw;$("#menuSoundToggle").checked=state.sound;$("#soundBtn").textContent=state.sound?"◖))":"静音";window.__monsterGameDiagnostics=()=>({...sounds.stats(),view:document.body.dataset.view,canvasCount:document.querySelectorAll("canvas.battle-fx").length,domParticles:document.querySelectorAll(".particle,.damage-number,.shockwave").length,hasFx:Boolean(state.fx)});bindEvents();document.addEventListener("pointerdown",()=>{if(state.sound&&document.body.dataset.view==="homeView")sounds.startMenu()},{once:true,passive:true});registerWebMCP();if("serviceWorker"in navigator)navigator.serviceWorker.register("./sw.js").catch(()=>{});if(!(matchMedia("(display-mode: standalone)").matches||navigator.standalone)&&/iPhone|iPad|iPod/.test(navigator.userAgent))$("#installBtn").classList.remove("hidden")}
init();
